import {safeLink,validateMenu} from './validation.js';
import {idFor,parseText,parseMenuText} from './menu-import.js';
import {flavorTags,foodTags,trainingFor} from './recommendations.js';
import {shuffle,createPractice,matchingClue,gradeMatching,gradeReview,queueMistakes,correctReviewIds} from './practice.js';
import {isGenericIngredient,normalizeIngredient} from './wikipedia.js';
import {sweetnessClasses,wineTypes,makeWineQuestion} from './wines.js';
import {drinkPhotos} from './photos.js';
import {getDocument,GlobalWorkerOptions} from 'pdfjs-dist/build/pdf.mjs';
GlobalWorkerOptions.workerSrc='/pdf.worker.min.mjs';
let lang=localStorage.getItem('mm-language')||'en',view='learn',catalog=[],glossary=[],progress=[],draft=null,selected=new Set(['signature','free','house']),session=null,search='',error='',busy=false,lessonMode='short',trainingId='',unlocked=false,loginBusy=false,authEpoch=0;
const trainingEdits=new Map();
const app=document.querySelector('#app'),dialog=document.querySelector('dialog');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=(en,de)=>lang==='en'?en:de;
const cats={signature:['Signature cocktails','Signature-Cocktails'],free:['Alcohol-free cocktails','Alkoholfreie Cocktails'],house:['Homemade drinks','Hausgemachte Drinks'],pairing:['Cocktail pairings','Cocktail-Pairings'],wine:['Wines & champagne','Wein & Champagner']};
const translations={'Dark rum':'Dunkler Rum','White rum':'Weißer Rum','Coconut rum':'Kokos-Rum','Mango':'Mango','Earl Grey tea':'Earl-Grey-Tee','Passion fruit':'Passionsfrucht','Lemon':'Zitrone','Lime':'Limette','Vanilla yogurt':'Vanillejoghurt','Miso banana':'Miso-Banane','Vietnamese coffee':'Vietnamesischer Kaffee','Maple syrup':'Ahornsirup','Chocolate bitters':'Schokoladenbitter','Pear eau-de-vie':'Birnenbrand','Pineapple distillate':'Ananasdestillat','Thai basil':'Thai-Basilikum','Granny Smith apple':'Granny-Smith-Apfel','Egg white':'Eiweiß','Pineapple':'Ananas','Coconut cream':'Kokoscreme','Kaffir lime leaves':'Kaffirlimettenblätter','Strawberry':'Erdbeere','Grapefruit':'Grapefruit','Vanilla':'Vanille','Szechuan pepper':'Szechuanpfeffer','Rhubarb soda':'Rhabarbersoda','Sugar syrup':'Zuckersirup','Raspberry':'Himbeere','Mint':'Minze','Cranberry':'Cranberry','Jasmine tea':'Jasmintee','Nashi pear':'Nashi-Birne','Lotus green tea':'Lotus-Grüntee','Elderflower':'Holunderblüte','Five spice syrup':'Fünf-Gewürze-Sirup','Roasted coconut':'Geröstete Kokosnuss','White chocolate':'Weiße Schokolade','Tonka bean':'Tonkabohne','Lemongrass':'Zitronengras','Coconut jelly':'Kokosnussgelee','Jasmine':'Jasmin','Blood orange':'Blutorange','Chamomile herbal liqueur':'Kamillen-Kräuterlikör','Pho spices':'Pho-Gewürze','Clarified lime':'Geklärte Limette','Thai basil oil':'Thai-Basilikumöl','Tom Yum spices':'Tom-Yum-Gewürze','Pink grapefruit lemonade':'Pink-Grapefruit-Limonade','Tom Yum salt':'Tom-Yum-Salz','Scotch whisky':'Scotch Whisky','Caramelized mango':'Karamellisierte Mango','Toasted rice coconut milk':'Gerösteter Reis mit Kokosmilch'};
Object.assign(translations,{'Planteray Dark Rum':'Planteray Dark Rum','Planteray 3 Stars White Rum':'Planteray 3 Stars White Rum','Planteray Cut & Dry Coconut Rum':'Planteray Cut & Dry Coconut Rum','Chai Infused Buffalo Trace Bourbon':'Buffalo Trace Bourbon mit Chai-Infusion','Blended Whisky':'Blended Whisky','Tequila Blanco':'Tequila Blanco','Jasmin Tea':'Jasmintee','Jasmin':'Jasmin','Clarified with Vanilla Yogurt':'Mit Vanillejoghurt geklärt','Cabernet Sauvignon Float':'Cabernet-Sauvignon-Float','Absinthe Spray':'Absinth-Spray','Miso Banana':'Miso-Banane','Fresh Pineapple':'Frische Ananas','Madagaskar Vanilla':'Madagaskar-Vanille','Yuzu–Calamansi Blend':'Yuzu-Calamansi-Mischung','Aloe Vera Juice':'Aloe-vera-Saft','Passionfruit':'Passionsfrucht','Tom Yum Salt Rim':'Tom-Yum-Salzrand'});
const translatedIngredients=Object.fromEntries(Object.entries(translations).map(([k,v])=>[normalizeIngredient(k),v]));
const ingredient=x=>lang==='de'?(translatedIngredients[normalizeIngredient(x)]||x):x;
const catName=c=>cats[c]?.[lang==='en'?0:1]||c;
const termFor=x=>[...glossary].sort((a,b)=>b.name.length-a.name.length).find(g=>normalizeIngredient(x)===normalizeIngredient(g.name)||(!['Dry','Off-dry','Brut','Extra Brut','Extra Dry'].includes(g.name)&&normalizeIngredient(x).includes(normalizeIngredient(g.name))));
function photo(d){if(d.category==='wine'){const type=d.wine?.type||'white',i=type==='red'?1:type==='rose'?2:type==='champagne'||type==='sparkling'?3:0;return `<figure class="drink-photo"><div class="wine-illustration" role="img" aria-label="${esc(t('Illustrative wine glass','Illustratives Weinglas'))}" style="background-position:${i%2*100}% ${Math.floor(i/2)*100}%"></div><figcaption>${t('Illustrative image · not the actual bottle','Illustratives Bild · nicht die tatsächliche Flasche')}</figcaption></figure>`;}const p=drinkPhotos[d.id];if(!p)return '';return `<figure class="drink-photo"><img class="drink-photo-original" src="${p.src}" width="${p.width}" height="${p.height}" alt="${esc(d.name)}" decoding="async"><figcaption>${t('From your drinks menu','Aus deiner Getränkekarte')} · ${t('page','Seite')} ${p.page}</figcaption></figure>`;}
function wineFacts(d){const w=d.wine||{},cls=sweetnessClasses[w.sweetness]||sweetnessClasses.unconfirmed;return `<div class="sweetness-label"><span>${t('Sweetness class','Süßeklasse')}</span>${w.sweetness&&w.sweetness!=='unconfirmed'?`<button class="chip known" data-term="${esc(cls.en)}">${esc(cls[lang])} ⓘ</button>`:`<strong>${esc(cls[lang])}</strong>`}</div><dl class="wine-facts"><dt>${t('Type','Weinart')}</dt><dd>${esc((wineTypes[w.type]||wineTypes.white)[lang])}</dd><dt>${t('Producer','Produzent')}</dt><dd>${esc(w.producer||t('Not specified','Nicht angegeben'))}</dd><dt>${t('Origin','Herkunft')}</dt><dd>${esc((w.region||t('Not specified','Nicht angegeben')).replace(/Austria/g,lang==='de'?'Österreich':'Austria').replace(/France/g,lang==='de'?'Frankreich':'France').replace(/Vienna/g,lang==='de'?'Wien':'Vienna'))}</dd><dt>${t('Vintage','Jahrgang')}</dt><dd>${esc(w.vintage||t('Not listed','Nicht angegeben'))}</dd><dt>${t('Grapes','Rebsorten')}</dt><dd>${esc(w.grapes?.length?w.grapes.join(' · '):t('Not specified in the menu','Nicht in der Karte angegeben'))}</dd></dl>${w.sweetnessSource?`<p class="wine-source">${t('Class source:','Quelle der Süßeklasse:')} ${safeLink(w.sweetnessSource.url)?`<a href="${esc(safeLink(w.sweetnessSource.url))}" target="_blank" rel="noopener noreferrer">${esc(w.sweetnessSource.label)}</a>`:esc(w.sweetnessSource.label)}</p>`:`<p class="wine-source">${t('Confirm the sweetness class against the bottle label or supplier sheet.','Süßeklasse anhand des Flaschenetiketts oder Lieferantendatenblatts bestätigen.')}</p>`}`;}
function winePrices(d){const w=d.wine;if(!w)return d.price!=null?`<p class="muted">€ ${Number(d.price).toFixed(2)}</p>`:'';return `<p class="muted">${w.glassPrice!=null?`${t('Glass','Glas')} ${w.glassVolume||0.125} l · € ${Number(w.glassPrice).toFixed(2)}<br>`:''}${w.bottlePrice!=null?`${t('Bottle','Flasche')} ${w.bottleVolume||0.75} l · € ${Number(w.bottlePrice).toFixed(2)}`:''}</p>`;}
function sweetnessGuide(){return `<aside class="panel wine-guide"><h3>${t('Dry is not the same as Extra Dry','Trocken ist nicht dasselbe wie Extra Dry')}</h3><p>${t('Still wines use classes such as Dry and Off-dry. Sparkling wines have their own scale: Extra Brut (0–6 g/L), Brut (less than 12 g/L), Extra Dry (12–17 g/L). Extra Dry is sweeter than Brut.','Stille Weine verwenden Klassen wie Trocken und Halbtrocken. Schaumweine haben eine eigene Skala: Extra Brut (0–6 g/L), Brut (weniger als 12 g/L), Extra Dry (12–17 g/L). Extra Dry ist süßer als Brut.')}</p><button class="btn secondary" data-term="Extra Dry">${t('Explain Extra Dry','Extra Dry erklären')}</button></aside>`;}
function chips(d){if(d.category==='wine')return '';return d.ingredients.map(i=>isGenericIngredient(i)?`<span class="chip">${esc(ingredient(i))}</span>`:`<button class="chip known" data-term="${esc(i)}" aria-label="${esc(t('Learn about ','Mehr erfahren über ')+ingredient(i))}">${esc(ingredient(i))} ⓘ</button>`).join('');}
async function api(path,body){if(body&&!(body instanceof FormData)&&new TextEncoder().encode(JSON.stringify(body)).length>3*1024*1024)throw Error(t('Menu data is too large. Split it into smaller uploads.','Die Menüdaten sind zu groß. Teile sie in kleinere Uploads auf.'));const epoch=authEpoch;const r=await fetch('/api/'+path,body?{method:'POST',body:body instanceof FormData?body:JSON.stringify(body),headers:body instanceof FormData?{}:{'Content-Type':'application/json'}}:{});let d;try{d=await r.json();}catch{throw Error(t('The server returned an unreadable response. Please retry.','Die Serverantwort war nicht lesbar. Bitte erneut versuchen.'));}if(epoch!==authEpoch)throw Error(t('Your sign-in changed. Please retry.','Deine Anmeldung hat sich geändert. Bitte erneut versuchen.'));if(!r.ok){if(r.status===401&&path!=='login'){clearPrivateState();render();}const messages={'Incorrect PIN.':t('Incorrect PIN.','Falsche PIN.'),'Too many attempts. Please try again in a few minutes.':t('Too many attempts. Please try again in a few minutes.','Zu viele Versuche. Bitte in einigen Minuten erneut versuchen.'),'Enter your PIN to continue.':t('Enter your PIN to continue.','Gib deine PIN ein, um fortzufahren.')};throw Error(messages[d.error]||d.error||t('Please try again.','Bitte erneut versuchen.'));}return d;}
let lookupController=null,lookupVersion=0;
dialog.addEventListener?.('close',()=>{lookupController?.abort();lookupVersion++;});
function ingredientDialog(name,body){dialog.innerHTML=`<div class="row space"><span class="eyebrow">${t('Ingredient guide','Zutatenwissen')}</span><button class="btn secondary" id="close-dialog" aria-label="${t('Close','Schließen')}">×</button></div><h2>${esc(ingredient(name))}</h2><div class="wiki-result" aria-live="polite">${body}</div>`;document.querySelector('#close-dialog').onclick=()=>dialog.close();const retry=document.querySelector('#retry-wiki');if(retry)retry.onclick=()=>showTerm(name);if(!dialog.open)dialog.showModal();}
async function showTerm(name){lookupController?.abort();const version=++lookupVersion;const saved=glossary.find(g=>g.name===name)||termFor(name);const classNames=['Dry','Off-dry','Brut','Extra Brut','Extra Dry'];if(classNames.includes(name)&&saved){ingredientDialog(name,`<p>${esc(saved.description[lang])}</p><a href="${esc(saved.url)}" target="_blank" rel="noopener noreferrer">${t('Reference','Quelle')}</a>`);return;}
 if(isGenericIngredient(name)){ingredientDialog(name,`<p>${t('This is a common ingredient. No lookup is needed.','Dies ist eine gängige Zutat. Eine Suche ist nicht nötig.')}</p>`);return;}
 lookupController=new AbortController();ingredientDialog(name,`${saved?`<p>${esc(saved.description[lang])}</p>`:''}<p class="muted" role="status">${t('Looking up Wikipedia…','Wikipedia wird durchsucht…')}</p>`);
 try{const response=await fetch('/api/wikipedia?q='+encodeURIComponent(name)+'&lang='+lang,{signal:lookupController.signal});if(version!==lookupVersion)return;if(response.status===401){clearPrivateState();error=t('Enter your PIN to continue.','Gib deine PIN ein, um fortzufahren.');render();return;}if(!response.ok)throw Error('Lookup unavailable');const result=await response.json();if(version!==lookupVersion||!dialog.open)return;
 if(result.status==='found'){const source=/^https:\/\/(en|de)\.wikipedia\.org\//.test(result.url)?result.url:null;ingredientDialog(name,`<p class="wiki-article-label">${t('Wikipedia article:','Wikipedia-Artikel:')} <strong>${esc(result.title)}</strong></p>${result.note==='alcohol-free'?`<p class="wiki-context">${t('Your menu lists an alcohol-free alternative. This article explains the brand or traditional drink category, not the alcohol content of that specific product.','Deine Karte nennt eine alkoholfreie Alternative. Dieser Artikel erklärt die Marke oder die traditionelle Getränkekategorie, nicht den Alkoholgehalt dieses konkreten Produkts.')}</p>`:result.related?`<p class="wiki-context">${t('General background on this topic; house preparations and individual brands may differ.','Allgemeines Hintergrundwissen zu diesem Thema; Hauszubereitungen und einzelne Marken können abweichen.')}</p>`:''}<p>${esc(result.extract)}</p>${result.language!==lang?`<p class="muted">${t('English article shown because a German article was unavailable.','Englischer Artikel, da kein deutscher Artikel verfügbar war.')}</p>`:''}${source?`<a href="${esc(source)}" target="_blank" rel="noopener noreferrer">${t('Read the full article on Wikipedia','Vollständigen Artikel auf Wikipedia lesen')}</a>`:''}`);
 }else{const notFound=result.status==='not-found';ingredientDialog(name,`${saved?`<p>${esc(saved.description[lang])}</p>`:''}<p class="muted">${notFound?t('No relevant Wikipedia article was found for this term.','Für diesen Begriff wurde kein passender Wikipedia-Artikel gefunden.'):t('Wikipedia could not be loaded right now. Please try again.','Wikipedia konnte gerade nicht geladen werden. Bitte erneut versuchen.')}</p><button class="btn secondary" id="retry-wiki">${t('Try again','Erneut versuchen')}</button>`);}
 }catch(e){if(e.name==='AbortError'||version!==lookupVersion||!dialog.open)return;ingredientDialog(name,`${saved?`<p>${esc(saved.description[lang])}</p>`:''}<p class="muted">${t('Wikipedia could not be loaded right now. Please try again.','Wikipedia konnte gerade nicht geladen werden. Bitte erneut versuchen.')}</p><button class="btn secondary" id="retry-wiki">${t('Try again','Erneut versuchen')}</button>`);}
}
function clearPrivateState(){authEpoch++;trainingEdits.clear();unlocked=false;catalog=[];glossary=[];progress=[];draft=null;session=null;view='learn';search='';lookupController?.abort();if(dialog.open)dialog.close();}
function renderLogin(){document.documentElement.lang=lang;app.innerHTML=`<header><div class="brand">Menu Mentor<span>MISS SAIGON · TEAM TRAINING</span></div><div class="lang"><button data-login-lang="en" class="${lang==='en'?'active':''}">EN</button><button data-login-lang="de" class="${lang==='de'?'active':''}">DE</button></div></header><main><section class="panel pin-login"><span class="eyebrow">${t('Team access','Teamzugang')}</span><h1>${t('Welcome back','Willkommen zurück')}</h1><p class="muted">${t('Enter the team PIN to open your training.','Gib die Team-PIN ein, um dein Training zu öffnen.')}</p><form id="pin-form"><label for="pin-code">PIN</label><input id="pin-code" name="pin" type="password" inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" autocomplete="current-password" required ${loginBusy?'disabled':''}><button class="btn" type="submit" ${loginBusy?'disabled':''}>${loginBusy?t('Signing in…','Anmeldung…'):t('Sign in','Anmelden')}</button></form>${error?`<p class="error" role="alert">${esc(error)}</p>`:''}</section></main>`;document.querySelectorAll('[data-login-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.loginLang;localStorage.setItem('mm-language',lang);renderLogin();});document.getElementById('pin-form').onsubmit=async e=>{e.preventDefault();if(loginBusy)return;const pin=document.getElementById('pin-code').value;if(!/^\d{4}$/.test(pin))return;loginBusy=true;error='';renderLogin();try{await api('login',{pin});await load();unlocked=true;}catch(e){clearPrivateState();error=e.message;}loginBusy=false;render();if(!unlocked)document.getElementById('pin-code')?.focus();};}
function render(){if(!unlocked)return renderLogin();document.documentElement.lang=lang;const nav=[['learn',t('Learn','Lernen')],['library',t('Drinks library','Getränkekarte')],['glossary',t('Ingredient guide','Zutatenwissen')],['manager',t('Manage menu','Menü verwalten')]];app.innerHTML=`<header><div class="brand">Menu Mentor<span>MISS SAIGON · TEAM TRAINING</span></div><button id="logout" class="btn secondary">${t('Sign out','Abmelden')}</button><div class="lang" aria-label="Language"><button data-lang="en" class="${lang==='en'?'active':''}">EN</button><button data-lang="de" class="${lang==='de'?'active':''}">DE</button></div></header><main><nav>${nav.map(([id,label])=>`<button data-view="${id}" class="${view===id?'active':''}">${label}</button>`).join('')}</nav>${error?`<div class="error" role="alert">${esc(error)}</div>`:''}${view==='learn'?learn():view==='library'?library():view==='glossary'?guide():manager()}<footer>${t('Training prototype · Progress is saved for this private workspace.','Trainingsprototyp · Der Fortschritt wird für diesen privaten Arbeitsbereich gespeichert.')}</footer></main>`;bind();}
function learn(){if(session)return quiz();const studied=progress.filter(p=>p.correct>0).length;return `<div class="intro"><div><span class="eyebrow">${t('A little practice, better service','Ein wenig Übung, besserer Service')}</span><h1>${t('Know the menu. Own the recommendation.','Menü kennen. Sicher empfehlen.')}</h1><p class="muted">${t('Choose your categories and practise the drinks you serve.','Wähle deine Kategorien und übe die Drinks, die du servierst.')}</p></div><div class="stat"><strong>${studied}<span style="font-size:16px;font-weight:400"> / ${catalog.length}</span></strong><span class="muted">${t('drinks practised','Drinks geübt')}</span></div></div><div class="layout"><section>${selected.has('wine')?sweetnessGuide():''}<h3>${t('What would you like to learn?','Was möchtest du lernen?')}</h3><div class="categories">${Object.keys(cats).filter(c=>catalog.some(d=>d.category===c)).map(c=>`<button class="category ${selected.has(c)?'selected':''}" data-category="${c}" aria-pressed="${selected.has(c)}"><span class="mark">${selected.has(c)?'✓':''}</span><span class="eyebrow">${c==='free'?'0%':c==='house'?'HOUSE':c==='pairing'?'PAIRING':c==='wine'?'WINE':'BAR'}</span><strong>${catName(c)}</strong><small>${catalog.filter(d=>d.category===c).length} ${t('drinks','Drinks')}</small></button>`).join('')}</div></section><aside class="panel session"><span class="eyebrow" style="color:#d5e7a0">${t('Your next session','Deine nächste Übung')}</span><h2>${lessonMode==='short'?t('One group · about 3–5 minutes','Eine Gruppe · etwa 3–5 Minuten'):catalog.filter(d=>selected.has(d.category)).length+' '+t('drinks in this lesson','Drinks in dieser Lektion')}</h2><p class="muted">${t('Meet a small group, then practise ingredients, differences and guest recommendations. Read the explanation before continuing.','Lerne eine kleine Gruppe kennen und übe dann Zutaten, Unterschiede und Gästeempfehlungen. Lies die Erklärung, bevor du weitergehst.')}</p><ol><li>${t('Read a short drink card','Kurze Getränkekarte lesen')}</li><li>${t('Choose, select or build an answer','Antwort wählen oder zusammensetzen')}</li><li>${t('Match, compare, and try true/false or spot-the-difference questions','Zuordnen, vergleichen und Richtig/Falsch- oder Unterschiedsfragen üben')}</li></ol><label for="lesson-mode">${t('Lesson length','Lektionslänge')}</label><select id="lesson-mode"><option value="short" ${lessonMode==='short'?'selected':''}>${t('Short lesson · about 3–5 minutes','Kurze Lektion · etwa 3–5 Minuten')}</option><option value="full" ${lessonMode==='full'?'selected':''}>${t('All selected categories','Alle gewählten Kategorien')}</option></select><p class="muted">${t('Short lessons focus on one category group. The next lesson prioritises drinks needing practice.','Kurze Lektionen behandeln eine Gruppe einer Kategorie. Die nächste Lektion priorisiert Drinks mit Übungsbedarf.')}</p><button id="start" class="btn lime" ${!catalog.some(d=>selected.has(d.category))?'disabled':''}>${t('Start practising','Übung starten')}</button><p class="muted" style="font-size:14px">${t('Missed drinks come back sooner. Tap underlined ingredients for an explanation.','Unsichere Drinks kommen früher wieder. Tippe auf unterstrichene Zutaten für eine Erklärung.')}</p></aside></div>`;}
function library(){return `<span class="eyebrow">${t('Your assortment','Dein Sortiment')}</span><h1>${t('Drinks library','Getränkekarte')}</h1><input class="search" id="search" placeholder="${t('Search drinks or ingredients…','Drinks oder Zutaten suchen…')}" aria-label="${t('Search drinks','Drinks suchen')}" value="${esc(search)}"><div class="cards">${catalog.filter(d=>([d.name,...d.ingredients,...d.ingredients.map(ingredient),d.description[lang],sweetnessClasses[d.wine?.sweetness]?.[lang],d.wine?.producer,d.wine?.region,d.wine?.vintage,...(d.wine?.grapes||[])].filter(Boolean).join(' ')).toLowerCase().includes(search.toLowerCase())).map(d=>`<article class="card"><span class="badge">${catName(d.category)}</span><h3>${esc(d.name)}</h3><p>${esc(d.description[lang])}</p>${d.category==='wine'?wineFacts(d):`<div class="ingredients">${chips(d)}</div>`}${winePrices(d)}</article>`).join('')||`<p>${t('No matching drinks.','Keine passenden Drinks.')}</p>`}</div>`;}
function guide(){return `<span class="eyebrow">${t('Small words, useful knowledge','Kleine Begriffe, nützliches Wissen')}</span><h1>${t('Ingredient guide','Zutatenwissen')}</h1><input id="search" class="search" placeholder="${t('Search verjus, calamansi, miso…','Verjus, Calamansi, Miso suchen…')}" aria-label="${t('Search ingredients','Zutaten suchen')}" value="${esc(search)}"><div class="glossary-list">${glossary.filter(g=>(g.name+' '+g.de+' '+g.description[lang]).toLowerCase().includes(search.toLowerCase())).map(g=>`<button class="term-card" data-term="${esc(g.name)}"><strong>${esc(lang==='de'?g.de:g.name)}</strong><p class="muted">${esc(g.description[lang])}</p></button>`).join('')||`<div class="panel"><p>${t('No saved explanation found.','Keine gespeicherte Erklärung gefunden.')}</p><button class="btn secondary" data-term="${esc(search)}">${t('Look up this term','Begriff nachschlagen')}</button></div>`}</div>`;}
function recommendationFacts(d){const p=trainingFor(d);return `<div class="recommendation-facts">${p.flavors.length?`<p><strong>${t('Flavour profile','Geschmacksprofil')}</strong><br>${p.flavors.map(k=>esc(flavorTags[k][lang])).join(' · ')}</p>`:''}${p.foodConfirmed&&p.foods.length?`<p><strong>${t('Recommend with','Empfehlen zu')}</strong><br>${p.foods.map(k=>esc(foodTags[k][lang])).join(' · ')}</p>`:''}<p><strong>${t('Say it to a guest','So erklärst du es einem Gast')}</strong><br>${esc(p.pitch[lang]||d.description[lang])}</p></div>`;}
function trainingEditor(){if(!catalog.length)return '';const d=catalog.find(d=>d.id===trainingId)||catalog[0],p=trainingEdits.get(d.id)||trainingFor(d);trainingId=d.id;return `<section class="panel training-editor"><h2>${t('Guest recommendations','Gästeempfehlungen')}</h2><p class="muted">${t('Review the flavour profile and food pairings used in lessons. Initial profiles use the existing drink descriptions. Confirm missing pairings with your team; unchecked profiles are excluded from guest questions.','Prüfe die Geschmacksprofile und Speisenempfehlungen der Lektionen. Ausgangsprofile stammen aus den vorhandenen Beschreibungen. Ergänze fehlende Kombinationen mit dem Team; unbestätigte Profile werden nicht abgefragt.')}</p><label for="training-drink">${t('Drink','Drink')}</label><select id="training-drink">${catalog.map(o=>`<option value="${esc(o.id)}" ${o.id===d.id?'selected':''}>${esc(o.name)}</option>`).join('')}</select><fieldset><legend>${t('Flavours','Geschmack')}</legend>${Object.entries(flavorTags).map(([k,v])=>`<label><input type="checkbox" data-flavor="${k}" ${p.flavors.includes(k)?'checked':''}> ${v[lang]}</label>`).join('')}</fieldset><label><input id="flavor-confirmed" type="checkbox" ${p.flavorConfirmed?'checked':''}> ${t('Flavour profile reviewed','Geschmacksprofil geprüft')}</label><fieldset><legend>${t('Food groups','Speisengruppen')}</legend>${Object.entries(foodTags).map(([k,v])=>`<label><input type="checkbox" data-food="${k}" ${p.foods.includes(k)?'checked':''}> ${v[lang]}</label>`).join('')}</fieldset><label><input id="food-confirmed" type="checkbox" ${p.foodConfirmed?'checked':''}> ${t('Food pairings reviewed','Speisenempfehlungen geprüft')}</label><label for="pitch-en">${t('Guest description · English','Gästebeschreibung · Englisch')}</label><textarea id="pitch-en" maxlength="600">${esc(p.pitch.en)}</textarea><label for="pitch-de">${t('Guest description · German','Gästebeschreibung · Deutsch')}</label><textarea id="pitch-de" maxlength="600">${esc(p.pitch.de)}</textarea><button id="save-training" class="btn" ${busy?'disabled':''}>${t('Save recommendation profile','Empfehlungsprofil speichern')}</button></section>`;}
function captureTraining(){if(!document.getElementById('pitch-en'))return;trainingEdits.set(trainingId,{flavors:[...document.querySelectorAll('[data-flavor]:checked')].map(x=>x.dataset.flavor),foods:[...document.querySelectorAll('[data-food]:checked')].map(x=>x.dataset.food),flavorConfirmed:document.getElementById('flavor-confirmed').checked,foodConfirmed:document.getElementById('food-confirmed').checked,pitch:{en:document.getElementById('pitch-en').value,de:document.getElementById('pitch-de').value}});}
function answerClass(id,rightIds){if(!session.answered)return session.picks.includes(id)?'selected':'';return session.picks.includes(id)?(rightIds.includes(id)?'good':'bad'):rightIds.includes(id)?(session.type===0?'good':'missed'):'';}
function answerLabel(id,rightIds){if(!session.answered)return session.picks.includes(id)?' ✓':'';return session.picks.includes(id)?(rightIds.includes(id)?' ✓':' ✕'):rightIds.includes(id)?(session.type===0?t(' · Correct answer',' · Richtige Antwort'):t(' · Correct, not selected',' · Richtig, nicht gewählt')):'';}
function checkIndividual(){const s=session;if(s.answered)return;s.ok=s.type===0?s.picks[0]===s.answerId:s.picks.length===s.right.length&&s.right.every(i=>s.picks.includes(i));s.answered=true;s.results=[{id:s.items[s.index].id,correct:s.ok}];if(s.ok)s.score++;queueMistakes(s,s.results);render();return saveAnswer();}
function checkReview(){const s=session;if(s.answered)return;const r=s.rounds[s.roundIndex];s.results=gradeReview(r,s.picks);s.ok=s.results.every(x=>x.correct);s.reviewScore+=s.results.filter(x=>x.correct).length;s.answered=true;queueMistakes(s,s.results);render();return saveAnswer();}
function start(){session=createPractice(catalog,selected,progress,shuffle,Math.random,lessonMode);if(session)prepare();render();}
function prepareReview(){const s=session,r=s.rounds[s.roundIndex];s.stage=r.kind==='matching'?'matching':'review-question';s.type=r.kind==='multiple'?1:0;s.picks=[];s.matches={};s.answered=false;s.saved=false;s.results=null;s.savedIds=new Set();s.attemptIds=new Map();s.saving=null;}
function matchingQuiz(){const s=session,round=s.rounds[s.roundIndex];return `<div class="quiz"><div class="row space"><span class="eyebrow">${catName(round.category)} · ${t('Group review','Gruppenübung')}</span><button id="exit" class="btn secondary">${t('End session','Übung beenden')}</button></div><div class="progress"><div style="width:${s.roundIndex/s.rounds.length*100}%"></div></div><p class="muted">${t('Group','Gruppe')} ${round.groupIndex+1} / ${s.groups.length} · ${t('Matching','Zuordnen')}</p><div class="panel"><h2>${t('Which drink belongs to each clue?','Welcher Drink gehört zu welchem Hinweis?')}</h2><p class="muted">${t('Match every description to a drink. Use each drink once.','Ordne jede Beschreibung einem Drink zu. Verwende jeden Drink einmal.')}</p><div class="matching-list">${round.rows.map((d,i)=>{const clue=matchingClue(d,lang),result=s.results?.find(r=>r.id===d.id),picked=round.options.find(o=>o.id===s.matches[d.id]);return `<section class="matching-row ${s.answered?(result.correct?'match-good':'match-bad'):''}"><label for="match-${i}">${t('Clue','Hinweis')} ${i+1}</label><p>${esc(clue.description)}</p>${clue.ingredients.length?`<p class="matching-ingredients">${clue.ingredients.map(x=>esc(ingredient(x))).join(' · ')}</p>`:''}<select id="match-${i}" data-match="${esc(d.id)}" ${s.answered?'disabled':''}><option value="">${t('Choose a drink…','Drink auswählen…')}</option>${round.options.map(o=>`<option value="${esc(o.id)}" ${s.matches[d.id]===o.id?'selected':''}>${esc(o.name)}</option>`).join('')}</select>${s.answered?`<p class="match-result"><strong>${result.correct?t('Correct','Richtig'):t('Correct match:','Richtige Zuordnung:')} ${esc(d.name)}</strong>${!result.correct?`<br>${t('Your answer:','Deine Antwort:')} ${esc(picked?.name||'')}`:''}</p>`:''}</section>`}).join('')}</div>${s.answered?`<div class="feedback ${s.results.every(r=>r.correct)?'feedback-good':'feedback-bad'}" role="status">${s.results.filter(r=>r.correct).length} / ${round.rows.length} ${t('correct matches','richtige Zuordnungen')}</div><button id="next" class="btn">${s.saved?t('Continue','Weiter'):t('Save answers and continue','Antworten speichern und weiter')}</button>`:`<button id="check-matches" class="btn" ${Object.keys(s.matches).length!==round.rows.length?'disabled':''}>${t('Check matches','Zuordnungen prüfen')}</button>`}</div></div>`;}
function variationQuiz(){const s=session,r=s.rounds[s.roundIndex],truth=r.kind==='true-false',clue=truth?matchingClue(r.claim,lang):null,actual=truth?matchingClue(r.target,lang):null;return `<div class="quiz"><div class="row space"><span class="eyebrow">${catName(r.category)} · ${t('Group review','Gruppenübung')}</span><button id="exit" class="btn secondary">${t('End session','Übung beenden')}</button></div><div class="progress"><div style="width:${s.roundIndex/s.rounds.length*100}%"></div></div><p class="muted">${t('Group','Gruppe')} ${r.groupIndex+1} / ${s.groups.length}</p><div class="panel"><span class="eyebrow">${truth?t('True or false','Richtig oder falsch'):t('Spot the difference','Unterschied erkennen')}</span><h2>${truth?t('Do these menu details belong to ','Gehören diese Menüdetails zu ')+esc(r.target.name)+'?':esc(r.prompt[lang])}</h2>${truth?`<p>${esc(clue.description)}</p>${clue.ingredients.length?`<p class="matching-ingredients">${clue.ingredients.map(i=>esc(ingredient(i))).join(' · ')}</p>`:''}`:`<p class="review-fact">${esc(r.ingredient?ingredient(r.ingredient):r.fact[lang])}</p>`}<p class="muted">${t('Choose one answer.','Wähle eine Antwort.')}</p>${r.options.map(o=>{const right=truth?o.id===r.answer:o.id===r.target.id;return `<button class="option ${answerClass(o.id,correctReviewIds(r))}" data-pick="${esc(o.id)}" ${s.answered?'disabled':''}>${esc(truth?o.label[lang]:o.name)}${answerLabel(o.id,correctReviewIds(r))}</button>`}).join('')}${s.answered?`<div class="feedback ${s.ok?'feedback-good':'feedback-bad'}" role="status"><strong>${s.ok?t('Correct!','Richtig!'):t('Let’s remember this one.','Das merken wir uns.')}</strong><p>${truth?(r.answer==='true'?t('True — these details match.','Richtig — diese Angaben passen.'):t('False — these details describe ','Falsch — diese Angaben beschreiben ')+esc(r.claim.name)+'.'):t('Correct answer: ','Richtige Antwort: ')+esc(r.target.name)}</p>${truth?`<p><strong>${esc(r.target.name)}</strong> — ${esc(actual.description)}</p>${actual.ingredients.length?`<p class="matching-ingredients">${actual.ingredients.map(i=>esc(ingredient(i))).join(' · ')}</p>`:''}`:''}</div><button id="next" class="btn">${s.saved?t('Continue','Weiter'):t('Save answer and continue','Antwort speichern und weiter')}</button>`:s.type===0?'':`<button id="check-review" class="btn" ${!s.picks.length?'disabled':''}>${t('Check answer','Antwort prüfen')}</button>`}</div></div>`;}
function guestQuiz(){const s=session,r=s.rounds[s.roundIndex];return `<div class="quiz"><div class="row space"><span class="eyebrow">${catName(r.category)} · ${t('Guest request','Gästewunsch')}</span><button id="exit" class="btn secondary">${t('End session','Übung beenden')}</button></div><p class="muted">${t('Group','Gruppe')} ${r.groupIndex+1} / ${s.groups.length}</p><div class="panel"><h2>${esc(r.prompt[lang])}</h2><p class="review-fact">${esc(r.fact[lang])}</p><p class="muted">${t('Choose one suitable drink from this learned group. More than one recommendation may be accepted.','Wähle einen passenden Drink aus dieser gelernten Gruppe. Mehrere Empfehlungen können akzeptiert werden.')}</p>${r.options.map(d=>`<button class="option ${answerClass(d.id,r.right)}" data-pick="${esc(d.id)}" ${s.answered?'disabled':''}>${esc(d.name)}${answerLabel(d.id,r.right)}</button>`).join('')}${s.answered?`<div class="feedback ${s.ok?'feedback-good':'feedback-bad'}" role="status"><strong>${s.ok?t('Good recommendation!','Gute Empfehlung!'):t('Compare the guest’s request with the profile.','Vergleiche den Gästewunsch mit dem Profil.')}</strong>${r.items.filter(d=>r.right.includes(d.id)).map(d=>`<p><strong>${esc(d.name)}</strong> — ${esc(trainingFor(d).pitch[lang]||d.description[lang])}</p>`).join('')}<p class="muted">${t('Accepted recommendations follow the recorded profiles for this group. Other pairings can be discussed with your team.','Akzeptierte Empfehlungen entsprechen den hinterlegten Profilen dieser Gruppe. Weitere Kombinationen kannst du mit dem Team besprechen.')}</p></div><button id="next" class="btn">${t('Continue','Weiter')}</button>`:''}</div></div>`;}
function reviewQuestion(){if(session.rounds[session.roundIndex].kind==='recommend')return guestQuiz();if(['true-false','difference'].includes(session.rounds[session.roundIndex].kind))return variationQuiz();const s=session,r=s.rounds[s.roundIndex],single=r.kind==='identify',clue=single?matchingClue(r.target,lang):null;return `<div class="quiz"><div class="row space"><span class="eyebrow">${catName(r.category)} · ${t('Group review','Gruppenübung')}</span><button id="exit" class="btn secondary">${t('End session','Übung beenden')}</button></div><div class="progress"><div style="width:${s.roundIndex/s.rounds.length*100}%"></div></div><p class="muted">${t('Group','Gruppe')} ${r.groupIndex+1} / ${s.groups.length}</p><div class="panel"><span class="eyebrow">${single?t('Single choice','Eine Antwort'):t('Multiple choice','Mehrere Antworten')}</span><h2>${single?t('Which of these drinks fits?','Welcher dieser Drinks passt?'):esc(r.prompt[lang])}</h2>${single?`<p>${esc(clue.description)}</p>${clue.ingredients.length?`<p class="matching-ingredients">${clue.ingredients.map(i=>esc(ingredient(i))).join(' · ')}</p>`:''}`:`<p class="review-fact">${esc(r.ingredient?ingredient(r.ingredient):r.fact[lang])}</p>`}<p class="muted">${single?t('Choose one drink from the group you just learned.','Wähle einen Drink aus der gerade gelernten Gruppe.'):t('Select every drink in this group that fits. More than one answer may be correct.','Wähle alle passenden Drinks aus dieser Gruppe. Mehrere Antworten können richtig sein.')}</p>${r.options.map(d=>{const correct=single?d.id===r.target.id:r.right.includes(d.id);return `<button class="option ${answerClass(d.id,correctReviewIds(r))}" data-pick="${esc(d.id)}" ${s.answered?'disabled':''}>${esc(d.name)}${answerLabel(d.id,correctReviewIds(r))}</button>`}).join('')}${s.answered?`<div class="feedback ${s.ok?'feedback-good':'feedback-bad'}" role="status"><strong>${s.ok?t('Correct!','Richtig!'):t('Let’s compare these again.','Vergleichen wir diese noch einmal.')}</strong><p>${t('Correct answer:','Richtige Antwort:')} ${esc(single?r.target.name:r.items.filter(d=>r.right.includes(d.id)).map(d=>d.name).join(' · '))}</p></div><button id="next" class="btn">${s.saved?t('Continue','Weiter'):t('Save answers and continue','Antworten speichern und weiter')}</button>`:s.type===0?'':`<button id="check-review" class="btn" ${!s.picks.length?'disabled':''}>${t('Check answer','Antwort prüfen')}</button>`}</div></div>`;}
function prepare(){const s=session,d=s.items[s.index];s.type=s.index%3;s.picks=[];s.answered=false;s.saved=false;s.savedIds=new Set();s.attemptIds=new Map();s.results=null;s.saving=null;s.answerId=d.id;s.wineQuestion=null;if(d.category==='wine'){s.type=0;s.wineQuestion=makeWineQuestion(d,s.index,catalog,shuffle);s.answerId=s.wineQuestion.answer;s.options=s.wineQuestion.options;return;}const group=s.groups.find(g=>g.some(x=>x.id===d.id));const other=shuffle(group.filter(c=>c.id!==d.id&&c.description[lang]!==d.description[lang]));if(s.type===0)s.options=shuffle([d,...other.slice(0,3)]).map(c=>({id:c.id,label:c.name}));else{const right=shuffle(d.ingredients).slice(0,Math.min(3,d.ingredients.length));const wrong=[...new Set(group.flatMap(c=>c.ingredients).filter(i=>!d.ingredients.includes(i)))];s.right=right;s.options=shuffle([...right,...shuffle(wrong).slice(0,3)]).map(i=>({id:i,label:ingredient(i)}));}}
function quiz(){const s=session;if(s.stage==='matching')return matchingQuiz();if(s.stage==='review-question')return reviewQuestion();if(s.stage==='compare-intro'){const r=s.rounds[s.roundIndex];return `<div class="quiz panel"><span class="eyebrow">${catName(r.category)} · ${t('Group review','Gruppenübung')}</span><h2>${t('Now tell these drinks apart.','Jetzt diese Drinks unterscheiden.')}</h2><p>${t('You have learned this group. Practise matching and comparing these drinks before learning the next group.','Du hast diese Gruppe gelernt. Übe jetzt, diese Drinks zuzuordnen und zu vergleichen, bevor du die nächste Gruppe lernst.')}</p><p class="muted">${s.rounds.filter(round=>round.groupIndex===r.groupIndex).length} ${t('exercises in this checkpoint','Übungen in diesem Checkpoint')}</p><ul class="review-drinks">${r.items.map(d=>`<li>${esc(d.name)}</li>`).join('')}</ul><p class="muted">${t('All answer options stay within this category and this learned group.','Alle Antwortmöglichkeiten bleiben in dieser Kategorie und dieser gelernten Gruppe.')}</p><button id="begin-review" class="btn">${t('Start group review','Gruppenübung starten')}</button><button id="exit" class="btn secondary">${t('End session','Übung beenden')}</button></div>`;}if(s.stage==='done')return `<div class="quiz panel completion"><span class="eyebrow">${t('Session complete','Übung abgeschlossen')}</span><h1>${t('A little more confident.','Ein wenig sicherer.')}</h1><strong>${s.score+s.reviewScore} / ${s.items.length+s.reviewTotal}</strong><p>${t('Individual questions:','Einzelfragen:')} ${s.score} / ${s.items.length}${s.reviewTotal?`<br>${t('Group review points:','Punkte der Gruppenübungen:')} ${s.reviewScore} / ${s.reviewTotal}`:''}</p><p class="muted">${s.mode==='short'?t('This short lesson covered one group. Start another lesson to keep learning.','Diese kurze Lektion hat eine Gruppe behandelt. Starte eine weitere Lektion, um weiterzulernen.'):t('Every selected drink was included.','Alle gewählten Drinks waren dabei.')} ${t('Your progress is saved. Mistakes were practised again.','Dein Fortschritt ist gespeichert. Fehler wurden erneut geübt.')}</p><button id="finish" class="btn">${t('Back to categories','Zurück zu Kategorien')}</button></div>`;const d=s.items[s.index];return `<div class="quiz"><div class="row space"><span class="eyebrow">${catName(d.category)}</span><button id="exit" class="btn secondary">${t('End session','Übung beenden')}</button></div><div class="progress"><div style="width:${(s.index/s.items.length)*100}%"></div></div><p class="muted">${s.index+1} / ${s.items.length}</p><div class="panel">${s.stage==='card'?`<span class="eyebrow">${t('Meet the drink','Lerne den Drink kennen')}</span><h2>${esc(d.name)}</h2><div class="drink-introduction ${drinkPhotos[d.id]||d.category==='wine'?'has-photo':''}">${photo(d)}<div><p class="drink-description">${esc(d.description[lang])}</p>${d.category==='wine'?wineFacts(d):`<div class="ingredients">${chips(d)}</div>`}</div></div>${recommendationFacts(d)}<div class="divider"></div><p class="muted">${d.category==='wine'?t('Tap the sweetness class for a short explanation.','Tippe auf die Süßeklasse für eine kurze Erklärung.'):t('Tap an ingredient if it is unfamiliar.','Tippe auf eine Zutat, wenn du sie nicht kennst.')}</p><button id="test" class="btn">${t('Continue','Weiter')}</button>`:`<span class="eyebrow">${s.type===0?t('Single choice','Eine Antwort'):s.type===1?t('Multiple choice','Mehrere Antworten'):t('Build from blocks','Aus Bausteinen bilden')}</span><h2>${s.wineQuestion?esc(s.wineQuestion.prompt[lang]):s.type===0?t('Which drink fits this description?','Welcher Drink passt zu dieser Beschreibung?'):t('Which ingredients belong to ','Welche Zutaten gehören zu ')+esc(d.name)+'?'}</h2>${s.type===0?`<p class="muted">${s.wineQuestion?t('Choose one answer.','Wähle eine Antwort.'):esc(d.description[lang])}</p>`:`<p class="muted">${t('Select all ingredients that belong to this drink.','Wähle alle Zutaten, die zu diesem Drink gehören.')}</p>`}${s.type===2?`<div class="block-area">${s.picks.map(i=>`<button class="chip ${answerClass(i,s.right)}" data-pick="${esc(i)}" ${s.answered?'disabled':''}>${esc(ingredient(i))}${s.answered?answerLabel(i,s.right):' ×'}</button>`).join('')||t('Your selected ingredients appear here.','Deine gewählten Zutaten erscheinen hier.')}</div><div class="blocks">${s.options.filter(o=>!s.picks.includes(o.id)).map(o=>`<button class="btn secondary ${answerClass(o.id,s.right)}" data-pick="${esc(o.id)}" ${s.answered?'disabled':''}>${esc(ingredient(o.id))}${answerLabel(o.id,s.right)}</button>`).join('')}</div>`:s.options.map(o=>`<button class="option ${answerClass(o.id,s.type===0?[s.answerId]:s.right)}" data-pick="${esc(o.id)}" ${s.answered?'disabled':''}>${esc(s.type===0?(typeof o.label==='object'?o.label[lang]:o.label):ingredient(o.id))}${answerLabel(o.id,s.type===0?[s.answerId]:s.right)}</button>`).join('')}${s.answered?`<div class="feedback ${s.ok?'feedback-good':'feedback-bad'}" role="status"><strong>${s.ok?t('Correct!','Richtig!'):t('Let’s remember this one.','Das merken wir uns.')}</strong><p>${s.wineQuestion?esc(s.wineQuestion.explanation[lang]):s.type===0?esc(d.name)+' — '+esc(d.description[lang]):t('Correct ingredients: ','Richtige Zutaten: ')+s.right.map(i=>esc(ingredient(i))).join(' · ')}</p>${d.category==='wine'?wineFacts(d):`<div class="ingredients">${chips(d)}</div>`}</div><button id="next" class="btn">${s.saved?t('Continue','Weiter'):t('Save answer and continue','Antwort speichern und weiter')}</button>`:s.type===0?'':`<button id="check" class="btn" ${!s.picks.length?'disabled':''}>${t('Check answer','Antwort prüfen')}</button>`}`}</div></div>`;}
function manager(){return `${trainingEditor()}<span class="eyebrow">${t('Keep the team up to date','Das Team auf dem Laufenden halten')}</span><h1>${t('A new menu, new lessons.','Neues Menü, neue Übungen.')}</h1><p class="muted">${t('Upload → review drinks → publish. Questions are generated from the approved ingredients and descriptions.','Hochladen → Drinks prüfen → veröffentlichen. Fragen entstehen aus den freigegebenen Zutaten und Beschreibungen.')}</p><div class="panel"><h3>${t('Upload your material','Material hochladen')}</h3><p class="muted">${t('PDF, TXT, CSV or JSON · max. 15 MB. PDF extraction is a draft: check names, ingredients and translations before publishing. Scanned PDFs need selectable text or a text export.','PDF, TXT, CSV oder JSON · max. 15 MB. Die PDF-Erkennung ist ein Entwurf: Namen, Zutaten und Übersetzungen vor Veröffentlichung prüfen. Gescannte PDFs benötigen auswählbaren Text oder einen Textexport.')}</p><div class="drop"><input type="file" id="upload" accept=".pdf,.txt,.csv,.json" aria-label="${t('Upload menu','Menü hochladen')}" ${busy?'disabled':''}><p class="muted">${busy?t('Reading your menu…','Menü wird gelesen…'):t('The original file and draft are saved privately.','Die Originaldatei und der Entwurf werden privat gespeichert.')}</p></div><button class="btn secondary" id="download-template">${t('Download CSV template','CSV-Vorlage herunterladen')}</button>${draft?`<div class="divider"></div><h3>${t('Review your draft','Entwurf prüfen')} · ${esc(draft.filename)}</h3><p class="muted">${draft.drinks.length} ${t('drinks detected. Edit the fields below. Both descriptions are required.','Drinks erkannt. Bearbeite die Felder unten. Beide Beschreibungen sind erforderlich.')}</p><div class="draft-grid">${draft.drinks.map((d,i)=>`<section class="card" data-draft-index="${i}"><label>${t('Drink name','Getränkename')}<input class="edit-input" data-field="name" value="${esc(d.name)}"></label><label>${t('Category','Kategorie')}<select data-field="category">${Object.keys(cats).map(c=>`<option value="${c}" ${d.category===c?'selected':''}>${catName(c)}</option>`).join('')}</select></label><label>${t('Ingredients (one per line)','Zutaten (eine pro Zeile)')}<textarea class="edit-text" data-field="ingredients">${esc(d.ingredients.join('\n'))}</textarea></label>${d.category==='wine'?`<label>${t('Wine type','Weinart')}<select data-field="wine-type">${Object.entries(wineTypes).map(([k,v])=>`<option value="${k}" ${(d.wine?.type||'white')===k?'selected':''}>${v[lang]}</option>`).join('')}</select></label><label>${t('Sweetness class','Süßeklasse')}<select data-field="sweetness">${Object.entries(sweetnessClasses).map(([k,v])=>`<option value="${k}" ${(d.wine?.sweetness||'unconfirmed')===k?'selected':''}>${v[lang]}</option>`).join('')}</select></label><label>${t('Producer','Produzent')}<input class="edit-input" data-field="producer" value="${esc(d.wine?.producer||'')}"></label><label>${t('Origin','Herkunft')}<input class="edit-input" data-field="region" value="${esc(d.wine?.region||'')}"></label><label>${t('Vintage','Jahrgang')}<input class="edit-input" data-field="vintage" value="${esc(d.wine?.vintage||'')}"></label>`:''}<label>English<textarea class="edit-text" data-field="en">${esc(d.description.en)}</textarea></label><label>Deutsch<textarea class="edit-text" data-field="de">${esc(d.description.de)}</textarea></label><button class="btn secondary" data-remove="${i}">${t('Remove from draft','Aus Entwurf entfernen')}</button></section>`).join('')}</div><label><input id="replace" type="checkbox"> ${t('Replace the whole menu (removes drinks absent from this upload)','Gesamtes Menü ersetzen (entfernt Drinks, die im Upload fehlen)')}</label><p class="muted">${t('Otherwise, matching names are updated and new drinks are added. Changed drinks restart their review progress.','Andernfalls werden gleiche Namen aktualisiert und neue Drinks ergänzt. Geänderte Drinks starten ihre Wiederholung neu.')}</p><div class="row"><button id="publish" class="btn" ${busy?'disabled':''}>${t('Approve & publish lessons','Übungen freigeben')}</button></div>`:''}</div>`;}
function bind(){on('logout',async()=>{try{await api('logout',{});clearPrivateState();error='';render();}catch(e){error=e.message;render();}});document.querySelectorAll('[data-draft-index] input,[data-draft-index] select,[data-draft-index] textarea').forEach(el=>el.oninput=()=>{draft.drinks=readDraft();if(el.dataset.field==='category')render()});document.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{draft.drinks=readDraft().filter((d,i)=>i!==Number(el.dataset.remove));render()});document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{captureTraining();lang=b.dataset.lang;localStorage.setItem('mm-language',lang);render();if(dialog.open)dialog.close();});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{captureTraining();view=b.dataset.view;search='';error='';render();});document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{selected.has(b.dataset.category)?selected.delete(b.dataset.category):selected.add(b.dataset.category);render();});document.querySelectorAll('[data-term]').forEach(b=>b.onclick=()=>showTerm(b.dataset.term));const searchInput=document.querySelector('#search');if(searchInput)searchInput.oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;render();const i=document.querySelector('#search');i.focus();i.setSelectionRange(pos,pos);};const mode=document.querySelector('#lesson-mode');if(mode)mode.onchange=()=>{lessonMode=mode.value;render();};const trainingSelect=document.querySelector('#training-drink');if(trainingSelect)trainingSelect.onchange=()=>{captureTraining();trainingId=trainingSelect.value;render();};document.querySelectorAll('.training-editor input,.training-editor textarea').forEach(el=>el.oninput=captureTraining);on('save-training',async()=>{if(busy)return;captureTraining();const training=trainingEdits.get(trainingId);const id=trainingId;busy=true;render();try{const data=await api('training',{id,training});catalog=data.drinks;trainingEdits.delete(id);if(data.changed!==false){session=null;progress=progress.filter(p=>p.id!==id);}error='';}catch(e){error=e.message;}busy=false;render();});on('start',start);on('test',()=>{const s=session;const groupIndex=s.groups.findIndex(g=>g.some(d=>d.id===s.items[s.index].id)),start=s.groups.slice(0,groupIndex).reduce((n,g)=>n+g.length,0),end=start+s.groups[groupIndex].length;if(s.index+1<end){s.index++;prepare();}else{s.index=start;s.stage='question';prepare();}render()});on('exit',()=>{session=null;render()});on('finish',()=>{session=null;render()});document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{const id=b.dataset.pick;if(session.answered)return;if(session.type===0){session.picks=[id];if(session.stage==='review-question')checkReview();else checkIndividual();}else{session.picks.includes(id)?session.picks=session.picks.filter(i=>i!==id):session.picks.push(id);render();}});on('begin-review',()=>{prepareReview();render()});document.querySelectorAll('[data-match]').forEach(el=>el.onchange=()=>{const s=session;if(s.answered)return;const row=el.dataset.match,value=el.value;for(const id of Object.keys(s.matches))if(s.matches[id]===value)delete s.matches[id];if(value)s.matches[row]=value;else delete s.matches[row];render();document.getElementById('match-'+s.rounds[s.roundIndex].rows.findIndex(d=>d.id===row))?.focus();});on('check-matches',async()=>{const s=session;if(s.answered)return;s.results=gradeMatching(s.rounds[s.roundIndex],s.matches);s.reviewScore+=s.results.filter(r=>r.correct).length;s.answered=true;queueMistakes(s,s.results);render();await saveAnswer()});on('check-review',checkReview);on('check',checkIndividual);on('next',async()=>{const s=session;if(s.advancing)return;s.advancing=true;if(!s.saved&&!await saveAnswer()){s.advancing=false;return;}if(session!==s)return;error='';if(s.stage==='matching'||s.stage==='review-question'){const checkpoint=s.rounds[s.roundIndex].afterIndex;s.roundIndex++;if(s.rounds[s.roundIndex]?.afterIndex===checkpoint)prepareReview();else if(s.index>=s.items.length)s.stage='done';else{s.stage='card';prepare();}}else{s.index++;if(s.rounds[s.roundIndex]?.afterIndex===s.index)prepareReview();else if(s.index>=s.items.length)s.stage='done';else{const boundary=s.groups.slice(0,-1).map((g,i)=>s.groups.slice(0,i+1).reduce((n,x)=>n+x.length,0)).includes(s.index);s.stage=boundary?'card':'question';prepare();}}s.advancing=false;render()});const u=document.querySelector('#upload');if(u)u.onchange=()=>upload(u.files[0]);on('download-template',()=>{download('menu-template.csv','name,category,ingredients,description_en,description_de\nMy new cocktail,signature,\"Gin|Calamansi|Soda\",\"Gin with calamansi and soda.\",\"Gin mit Calamansi und Soda.\"\n')});on('preview-draft',()=>{try{draft.drinks=readDraft();render()}catch(e){error=t('Invalid JSON. Check commas and quotation marks.','Ungültiges JSON. Kommas und Anführungszeichen prüfen.');render()}});on('publish',async()=>{let drinks;try{drinks=readDraft()}catch(e){error=t('Invalid JSON. Check commas and quotation marks.','Ungültiges JSON. Kommas und Anführungszeichen prüfen.');return render()}const replace=document.querySelector('#replace').checked;draft.drinks=drinks;busy=true;render();try{await api('publish',{drinks,replace});session=null;trainingEdits.clear();await load();draft=null;view='library';error='';}catch(e){error=e.message}busy=false;render()});}
function readDraft(){return [...document.querySelectorAll('[data-draft-index]')].map(el=>{const d=draft.drinks[Number(el.dataset.draftIndex)];const val=f=>el.querySelector('[data-field="'+f+'"]').value;const wine=val('category')==='wine'?{...d.wine,type:el.querySelector('[data-field="wine-type"]')?.value||d.wine?.type||'white',sweetness:el.querySelector('[data-field="sweetness"]')?.value||d.wine?.sweetness||'unconfirmed',producer:el.querySelector('[data-field="producer"]')?.value||d.wine?.producer||'',region:el.querySelector('[data-field="region"]')?.value||d.wine?.region||'',vintage:el.querySelector('[data-field="vintage"]')?.value||d.wine?.vintage||null,grapes:val('ingredients').split('\n').map(x=>x.trim()).filter(Boolean)}:undefined;if(wine&&wine.sweetness!==d.wine?.sweetness)wine.sweetnessSource=wine.sweetness==='unconfirmed'?null:{label:'Manager confirmed'};return {...d,wine,name:val('name'),category:val('category'),ingredients:val('ingredients').split('\n').map(x=>x.trim()).filter(Boolean),description:{en:val('en'),de:val('de')}}})}
function on(id,fn){const el=document.getElementById(id);if(el)el.onclick=fn}
async function saveAnswer(){const s=session;if(s.saved)return true;if(s.saving)return s.saving;s.saving=(async()=>{try{for(const result of s.results||[]){if(s.savedIds.has(result.id))continue;if(!s.attemptIds.has(result.id))s.attemptIds.set(result.id,crypto.randomUUID());const p=await api('answer',{id:result.id,correct:result.correct,attemptId:s.attemptIds.get(result.id)});progress=progress.filter(x=>x.id!==p.id).concat(p);s.savedIds.add(result.id);}s.saved=true;if(session===s){error='';render();}return true}catch(e){if(session===s){error=e.message;render();}return false}})();const saved=await s.saving;s.saving=null;return saved;}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
async function readPdf(file){const pdf=await getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;try{let text='';for(let n=1;n<=pdf.numPages;n++){const page=await pdf.getPage(n),content=await page.getTextContent();let lastY=null;for(const item of content.items){if(lastY!==null&&Math.abs(item.transform[5]-lastY)>3)text+='\n';text+=item.str+' ';lastY=item.transform[5]}text+='\n'}return parseText(text);}finally{await pdf.destroy();}}
async function upload(file){if(!file)return;if(file.size>15*1024*1024){error=t('Choose a file under 15 MB.','Datei unter 15 MB wählen.');return render()}busy=true;error='';render();try{let items;if(file.name.toLowerCase().endsWith('.pdf')){items=await readPdf(file);}else items=parseMenuText(file.name,await file.text());if(!items?.length)throw Error(t('No drinks could be extracted. Use the CSV template, or a text PDF with a drink name followed by ingredients separated by •.','Keine Drinks erkannt. Nutze die CSV-Vorlage oder ein Text-PDF mit Getränkenamen und durch • getrennten Zutaten.'));items=validateMenu(items.map(d=>({...d,id:d?.id||idFor(d?.name||'')})));const upload=await api('upload-url',{filename:file.name,size:file.size});const uploaded=await fetch(upload.uploadUrl,{method:'PUT',headers:{'Content-Type':upload.contentType},body:file});if(!uploaded.ok)throw Error(t('The original file could not be uploaded. Please retry.','Die Originaldatei konnte nicht hochgeladen werden. Bitte erneut versuchen.'));draft=await api('draft',{uploadId:upload.uploadId,drinks:items});}catch(e){error=e.message}busy=false;render()}
async function load(){const data=await api('catalog');catalog=data.drinks;glossary=data.glossary;progress=data.progress;draft=data.draft;}
try{const access=await api('session');if(access.unlocked){await load();unlocked=true;}}catch(e){error=e.message}render();
if(document.modelContext?.registerTool){for(const tool of [{name:'search_ingredients',description:'Search the ingredient guide and show matching explanations.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute:({query})=>{if(!unlocked)throw Error('Sign in with your PIN first.');if(typeof query!=='string')throw Error('query must be text');view='glossary';search=query;render();return glossary.filter(g=>(g.name+' '+g.de).toLowerCase().includes(query.toLowerCase()))}},{name:'start_drinks_practice',description:'Start a practice session for chosen menu categories.',inputSchema:{type:'object',properties:{categories:{type:'array',items:{type:'string',enum:Object.keys(cats)},minItems:1}},required:['categories'],additionalProperties:false},execute:({categories})=>{if(!unlocked)throw Error('Sign in with your PIN first.');if(!Array.isArray(categories)||!categories.length||categories.some(c=>!cats[c])||!catalog.some(d=>categories.includes(d.category)))throw Error('Choose available categories');selected=new Set(categories);view='learn';start();return{started:true,drinks:session.items.length}}}])Promise.resolve(document.modelContext.registerTool(tool)).catch(console.error)}
